//! Benchmarks for line counting

use criterion::{criterion_group, criterion_main, Criterion};
use maram::stats::count_lines;
use std::io::Write;
use tempfile::NamedTempFile;
use std::hint::black_box;

fn create_file_with_lines(lines: usize) -> NamedTempFile {
    let mut file = NamedTempFile::new().unwrap();
    for i in 0..lines {
        writeln!(file, "This is line number {}", i).unwrap();
    }
    file.flush().unwrap();
    file
}

fn benchmark_small_file(c: &mut Criterion) {
    let file = create_file_with_lines(100);

    c.bench_function("count_lines_100", |b| {
        b.iter(|| {
            let _ = count_lines(black_box(file.path()), 10_000_000).unwrap();
        });
    });
}

fn benchmark_medium_file(c: &mut Criterion) {
    let file = create_file_with_lines(10_000);

    c.bench_function("count_lines_10k", |b| {
        b.iter(|| {
            let _ = count_lines(black_box(file.path()), 10_000_000).unwrap();
        });
    });
}

fn benchmark_large_file(c: &mut Criterion) {
    let file = create_file_with_lines(100_000);

    c.bench_function("count_lines_100k", |b| {
        b.iter(|| {
            let _ = count_lines(black_box(file.path()), 100_000_000).unwrap();
        });
    });
}

fn benchmark_binary_detection(c: &mut Criterion) {
    // Create a binary file
    let mut file = NamedTempFile::new().unwrap();
    file.write_all(&[0, 1, 2, 3, 255, 254, 253]).unwrap();
    file.flush().unwrap();

    c.bench_function("binary_detection", |b| {
        b.iter(|| {
            let _ = count_lines(black_box(file.path()), 10_000_000).unwrap();
        });
    });
}

criterion_group!(
    benches,
    benchmark_small_file,
    benchmark_medium_file,
    benchmark_large_file,
    benchmark_binary_detection
);
criterion_main!(benches);

//! maram - CLI entry point
//!
//! This module contains the main function that serves as the entry point
//! for the maram command-line tool. It handles argument parsing, configuration
//! loading, logging setup, and delegates to the core library functions.

#[cfg(feature = "jemalloc")]
use tikv_jemallocator::Jemalloc;

#[cfg(feature = "jemalloc")]
#[global_allocator]
static GLOBAL: Jemalloc = Jemalloc;

use clap::Parser;
use env_logger::Env;
use maram::{run_tree, Args, Config, Result};
use std::error::Error;
use std::path::Path;
use std::process;

fn main() {
    // Initialize logger with RUST_LOG env var support
    env_logger::Builder::from_env(Env::default().default_filter_or("warn")).init();

    // Run the main logic
    if let Err(e) = run() {
        log::error!("Error: {}", e);
        eprintln!("Error: {}", e);

        // Print chain of errors if any
        let mut source = e.source();
        while let Some(err) = source {
            eprintln!("  Caused by: {}", err);
            source = err.source();
        }

        process::exit(1);
    }
}

/// Main application logic
///
/// This function handles configuration loading, validates arguments,
/// and calls the tree traversal and display functions.
fn run() -> Result<()> {
    let args = Args::parse();

    // Load configuration from ~/.maram.toml if it exists
    let config = Config::load()?;

    // Get the target path
    let path = Path::new(&args.path);

    // Validate path exists
    if !path.exists() {
        return Err(maram::Error::IoError(std::io::Error::new(
            std::io::ErrorKind::NotFound,
            format!("Path does not exist: {}", path.display()),
        )));
    }

    // Enable verbose logging if requested
    if args.verbose {
        log::set_max_level(log::LevelFilter::Debug);
    }

    // Run the tree command
    let start = std::time::Instant::now();
    run_tree(path, &args, &config)?;

    // Show timing info if benchmarking
    if args.bench {
        let elapsed = start.elapsed();
        eprintln!("\nExecution time: {:.3}s", elapsed.as_secs_f64());
    }

    Ok(())
}

//! Error types for maram
//!
//! This module defines all custom error types used throughout the application.
//! We use thiserror to derive Error trait implementations with zero runtime overhead.

use thiserror::Error;

/// Result type alias for maram operations
pub type Result<T> = std::result::Result<T, Error>;

/// Main error type for maram
#[derive(Error, Debug)]
pub enum Error {
    /// I/O errors from filesystem operations
    #[error("I/O error: {0}")]
    IoError(#[from] std::io::Error),

    /// Regex compilation errors
    #[error("Invalid regex pattern: {0}")]
    RegexError(#[from] regex::Error),

    /// Configuration file parsing errors
    #[error("Configuration error: {0}")]
    ConfigError(String),

    /// TOML parsing errors
    #[error("TOML parsing error: {0}")]
    TomlError(#[from] toml::de::Error),

    /// JSON serialization errors
    #[error("JSON error: {0}")]
    JsonError(#[from] serde_json::Error),

    /// Size parsing errors
    #[error("Invalid size format: {0}")]
    SizeParseError(String),

    /// Time parsing errors
    #[error("Invalid time format: {0}")]
    TimeParseError(String),

    /// Thread pool errors
    #[error("Thread pool error: {0}")]
    ThreadPoolError(String),

    /// Path errors
    #[error("Invalid path: {0}")]
    PathError(String),

    /// Permission errors
    #[error("Permission denied: {0}")]
    PermissionError(String),

    /// Git-related errors
    #[error("Git error: {0}")]
    GitError(String),

    /// General errors
    #[error("{0}")]
    General(String),
}

impl Error {
    /// Create a new general error with a custom message
    pub fn general<S: Into<String>>(msg: S) -> Self {
        Error::General(msg.into())
    }

    /// Create a new configuration error
    pub fn config<S: Into<String>>(msg: S) -> Self {
        Error::ConfigError(msg.into())
    }

    /// Create a new size parse error
    pub fn size_parse<S: Into<String>>(msg: S) -> Self {
        Error::SizeParseError(msg.into())
    }

    /// Create a new time parse error
    pub fn time_parse<S: Into<String>>(msg: S) -> Self {
        Error::TimeParseError(msg.into())
    }

    /// Create a new path error
    pub fn path<S: Into<String>>(msg: S) -> Self {
        Error::PathError(msg.into())
    }

    /// Create a new permission error
    pub fn permission<S: Into<String>>(msg: S) -> Self {
        Error::PermissionError(msg.into())
    }
}

