use std::fs::File;
use std::io::Write as _;

use maram::{
    collect, generate, generate_to_writer, render, render_to_writer, DistributionFormat,
    DistributionType, FilterOptions, MaramOptions, OutputFormat, SortBy,
};
use regex::Regex;

fn main() -> maram::Result<()> {
    let path = ".";

    // Build filter options
    let filter = FilterOptions {
        show_hidden: false,
        gitignore: true,
        max_depth: Some(3),
        max_dirs: Some(5),
        max_files: Some(10),
        sort_by: Some(SortBy::Name),
        reverse_sort: false,
        include: Some(Regex::new(r"\.(rs|toml|md)$").unwrap()),
        exclude: Some(Regex::new(r"(^|/)target(/|$)").unwrap()),
        ..Default::default()
    };

    // Build formatting and execution options
    let mut opts = MaramOptions { output: OutputFormat::Tree, filter, ..Default::default() };
    // tweak format/color preferences
    opts.format.unicode = true;
    opts.format.color = atty::is(atty::Stream::Stdout);
    opts.format.full_path = false;
    opts.format.show_size = true;
    // line counting, dir sizes, total summary
    opts = opts.with_line_counting(10 * 1024 * 1024).with_dir_sizes().with_total_size();
    // threads and distribution
    opts.threads = 0;
    opts.distribution = Some((DistributionType::Ext, 8, DistributionFormat::Table));

    // 1) One-shot generation as String
    let tree = generate(path, &opts)?;
    println!("{}", tree);

    // 2) Stream directly to a writer (e.g., a file)
    let mut tree_file = File::create("maram_tree.txt")?;
    generate_to_writer(path, &opts, &mut tree_file)?;
    writeln!(tree_file, "\n# Generated by maram")?;

    // 3) Collect structured entries, then render to different formats
    let entries = collect(path, &opts)?;

    // Render JSON as String
    let mut json_opts = opts.clone();
    json_opts.output = OutputFormat::Json;
    // distribution and totals are ignored for JSON/CSV
    let json = render(&entries, &json_opts)?;
    println!(
        "JSON output (truncated): {}",
        &json.chars().take(120).collect::<String>()
    );

    // Render CSV to a file
    let mut csv_opts = opts.clone();
    csv_opts.output = OutputFormat::Csv;
    let mut csv_file = File::create("maram_tree.csv")?;
    render_to_writer(&entries, &csv_opts, &mut csv_file)?;

    // 4) Plain list format
    let mut plain_opts = opts.clone();
    plain_opts.output = OutputFormat::Plain;
    let plain = render(&entries, &plain_opts)?;
    println!(
        "\nPlain list (truncated):\n{}",
        &plain.lines().take(10).collect::<Vec<_>>().join("\n")
    );

    Ok(())
}

//! Benchmarks for filesystem traversal

use criterion::{criterion_group, criterion_main, Criterion};
use maram::{FilterOptions, Walker};
use std::fs::{self, File};
use std::io::Write;
use std::path::Path;
use tempfile::TempDir;
use std::hint::black_box;

/// Create a large directory tree for benchmarking
fn create_benchmark_tree(depth: usize, files_per_dir: usize, dirs_per_dir: usize) -> TempDir {
    let temp_dir = TempDir::new().unwrap();
    create_tree_recursive(temp_dir.path(), depth, files_per_dir, dirs_per_dir);
    temp_dir
}

fn create_tree_recursive(path: &Path, depth: usize, files_per_dir: usize, dirs_per_dir: usize) {
    if depth == 0 {
        return;
    }

    // Create files
    for i in 0..files_per_dir {
        let file_path = path.join(format!("file_{}.txt", i));
        let mut file = File::create(file_path).unwrap();
        writeln!(file, "This is test file {}", i).unwrap();
    }

    // Create subdirectories
    for i in 0..dirs_per_dir {
        let dir_path = path.join(format!("dir_{}", i));
        fs::create_dir(&dir_path).unwrap();
        create_tree_recursive(&dir_path, depth - 1, files_per_dir, dirs_per_dir);
    }
}

fn benchmark_small_tree(c: &mut Criterion) {
    let temp_dir = create_benchmark_tree(3, 10, 3);
    let path = temp_dir.path();

    c.bench_function("traverse_small_tree", |b| {
        b.iter(|| {
            let filter_opts = FilterOptions::default();
            let mut walker = Walker::new(black_box(path), filter_opts, 1).unwrap();
            let _ = walker.walk().unwrap();
        });
    });
}

fn benchmark_large_tree(c: &mut Criterion) {
    let temp_dir = create_benchmark_tree(4, 20, 4);
    let path = temp_dir.path();

    c.bench_function("traverse_large_tree", |b| {
        b.iter(|| {
            let filter_opts = FilterOptions::default();
            let mut walker = Walker::new(black_box(path), filter_opts, 1).unwrap();
            let _ = walker.walk().unwrap();
        });
    });
}

fn benchmark_parallel_traversal(c: &mut Criterion) {
    let temp_dir = create_benchmark_tree(4, 20, 4);
    let path = temp_dir.path();

    c.bench_function("traverse_parallel", |b| {
        b.iter(|| {
            let filter_opts = FilterOptions::default();
            let mut walker = Walker::new(black_box(path), filter_opts, 0).unwrap(); // 0 = auto threads
            let _ = walker.walk().unwrap();
        });
    });
}

fn benchmark_filtered_traversal(c: &mut Criterion) {
    let temp_dir = create_benchmark_tree(4, 20, 4);
    let path = temp_dir.path();

    c.bench_function("traverse_filtered", |b| {
        b.iter(|| {
            let filter_opts = FilterOptions { include: Some(regex::Regex::new(r"file_1").unwrap()), ..Default::default() };
            let mut walker = Walker::new(black_box(path), filter_opts, 1).unwrap();
            let _ = walker.walk().unwrap();
        });
    });
}

criterion_group!(
    benches,
    benchmark_small_tree,
    benchmark_large_tree,
    benchmark_parallel_traversal,
    benchmark_filtered_traversal
);
criterion_main!(benches);

//! Benchmarks comparing maram's custom walker with walkdir

use criterion::{criterion_group, criterion_main, Criterion};
use maram::{FilterOptions, Walker};
use std::fs::{self, File};
use std::io::Write;
use std::path::Path;
use tempfile::TempDir;
use walkdir::WalkDir;
use std::hint::black_box;

/// Create a large directory tree for benchmarking
fn create_benchmark_tree(depth: usize, files_per_dir: usize, dirs_per_dir: usize) -> TempDir {
    let temp_dir = TempDir::new().unwrap();
    create_tree_recursive(temp_dir.path(), depth, files_per_dir, dirs_per_dir);
    temp_dir
}

fn create_tree_recursive(path: &Path, depth: usize, files_per_dir: usize, dirs_per_dir: usize) {
    if depth == 0 {
        return;
    }

    // Create files
    for i in 0..files_per_dir {
        let file_path = path.join(format!("file_{}.txt", i));
        let mut file = File::create(file_path).unwrap();
        writeln!(file, "This is test file {}", i).unwrap();
    }

    // Create subdirectories
    for i in 0..dirs_per_dir {
        let dir_path = path.join(format!("dir_{}", i));
        fs::create_dir(&dir_path).unwrap();
        create_tree_recursive(&dir_path, depth - 1, files_per_dir, dirs_per_dir);
    }
}

fn benchmark_maram_vs_walkdir(c: &mut Criterion) {
    let temp_dir = create_benchmark_tree(4, 10, 3);
    let path = temp_dir.path();

    let mut group = c.benchmark_group("walker_comparison");

    // Benchmark walkdir
    group.bench_function("walkdir", |b| {
        b.iter(|| {
            let walker = WalkDir::new(black_box(path));
            let count = walker.into_iter().filter_map(|e| e.ok()).count();
            black_box(count);
        });
    });

    // Benchmark maram (single-threaded)
    group.bench_function("maram_single", |b| {
        b.iter(|| {
            let filter_opts = FilterOptions::default();
            let mut walker = Walker::new(black_box(path), filter_opts, 1).unwrap();
            let entries = walker.walk().unwrap();
            black_box(entries.len());
        });
    });

    // Benchmark maram (multi-threaded)
    group.bench_function("maram_parallel", |b| {
        b.iter(|| {
            let filter_opts = FilterOptions::default();
            let mut walker = Walker::new(black_box(path), filter_opts, 0).unwrap();
            let entries = walker.walk().unwrap();
            black_box(entries.len());
        });
    });

    group.finish();
}

fn benchmark_with_filtering(c: &mut Criterion) {
    let temp_dir = create_benchmark_tree(4, 20, 4);
    let path = temp_dir.path();

    let mut group = c.benchmark_group("filtered_walker_comparison");

    // Benchmark walkdir with filtering
    group.bench_function("walkdir_filtered", |b| {
        b.iter(|| {
            let walker = WalkDir::new(black_box(path));
            let count = walker
                .into_iter()
                .filter_map(|e| e.ok())
                .filter(|e| e.file_name().to_string_lossy().contains("file_1"))
                .count();
            black_box(count);
        });
    });

    // Benchmark maram with filtering
    group.bench_function("maram_filtered", |b| {
        b.iter(|| {
            let filter_opts = FilterOptions { include: Some(regex::Regex::new(r"file_1").unwrap()), ..Default::default() };
            let mut walker = Walker::new(black_box(path), filter_opts, 1).unwrap();
            let entries = walker.walk().unwrap();
            black_box(entries.len());
        });
    });

    group.finish();
}

fn benchmark_large_tree(c: &mut Criterion) {
    // Create a larger tree for more realistic benchmarks
    let temp_dir = create_benchmark_tree(5, 20, 3);
    let path = temp_dir.path();

    let mut group = c.benchmark_group("large_tree");
    group.sample_size(10); // Reduce sample size for large trees

    group.bench_function("walkdir_large", |b| {
        b.iter(|| {
            let walker = WalkDir::new(black_box(path));
            let count = walker.into_iter().filter_map(|e| e.ok()).count();
            black_box(count);
        });
    });

    group.bench_function("maram_large_single", |b| {
        b.iter(|| {
            let filter_opts = FilterOptions::default();
            let mut walker = Walker::new(black_box(path), filter_opts, 1).unwrap();
            let entries = walker.walk().unwrap();
            black_box(entries.len());
        });
    });

    group.bench_function("maram_large_parallel", |b| {
        b.iter(|| {
            let filter_opts = FilterOptions::default();
            let mut walker = Walker::new(black_box(path), filter_opts, 0).unwrap();
            let entries = walker.walk().unwrap();
            black_box(entries.len());
        });
    });

    group.finish();
}

criterion_group!(
    benches,
