);
criterion_main!(benches);

//! Configuration file handling
//!
//! This module manages loading and parsing configuration from ~/.maram.toml

use crate::filters::SortBy;
use crate::{Error, Result};
use serde::{Deserialize, Serialize};
use std::fs;
use std::path::PathBuf;

/// Main configuration structure
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct Config {
    /// Display options
    #[serde(default)]
    pub display: DisplayConfig,

    /// Filter options
    #[serde(default)]
    pub filters: FilterConfig,

    /// Performance options
    #[serde(default)]
    pub performance: PerformanceConfig,
}

/// Display configuration
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DisplayConfig {
    /// Use Unicode characters by default
    #[serde(default)]
    pub unicode: bool,

    /// Show file sizes by default
    #[serde(default = "default_true")]
    pub show_size: bool,

    /// Show line counts by default
    #[serde(default)]
    pub show_lines: bool,

    /// Show directory sizes by default
    #[serde(default)]
    pub dir_sizes: bool,

    /// Show total size by default
    #[serde(default = "default_true")]
    pub total_size: bool,
}

/// Filter configuration
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct FilterConfig {
    /// Show hidden files by default
    #[serde(default)]
    pub show_hidden: bool,

    /// Respect gitignore by default
    #[serde(default)]
    pub gitignore: bool,

    /// Default max depth
    #[serde(default)]
    pub max_depth: Option<usize>,

    /// Default max directories per level
    #[serde(default)]
    pub max_dirs: Option<usize>,

    /// Default max files per level
    #[serde(default)]
    pub max_files: Option<usize>,

    /// Default sort field
    #[serde(default)]
    pub sort_by: Option<SortBy>,

    /// Reverse sort by default
    #[serde(default)]
    pub reverse_sort: bool,
}

/// Performance configuration
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PerformanceConfig {
    /// Number of threads (0 = auto)
    #[serde(default)]
    pub threads: usize,

    /// Maximum file size for line counting
    #[serde(default = "default_max_file_size")]
    pub max_file_size: u64,
}

impl Default for DisplayConfig {
    fn default() -> Self {
        Self {
            unicode: true,
            show_size: true,
            show_lines: false,
            dir_sizes: false,
            total_size: true,
        }
    }
}

// Default is derived above

impl Default for PerformanceConfig {
    fn default() -> Self {
        Self {
            threads: 0,
            max_file_size: 1_073_741_824, // 1GB
        }
    }
}

impl Config {
    /// Load configuration from ~/.maram.toml
    pub fn load() -> Result<Self> {
        let config_path = get_config_path()?;

        if !config_path.exists() {
            log::debug!("No config file found at {:?}, using defaults", config_path);
            return Ok(Self::default());
        }

        log::debug!("Loading config from {:?}", config_path);
        let content = fs::read_to_string(&config_path)
            .map_err(|e| Error::config(format!("Failed to read config file: {}", e)))?;

        let config: Config = toml::from_str(&content)?;

        Ok(config)
    }

    /// Save configuration to ~/.maram.toml
    pub fn save(&self) -> Result<()> {
        let config_path = get_config_path()?;

        // Ensure parent directory exists
        if let Some(parent) = config_path.parent() {
            fs::create_dir_all(parent)
                .map_err(|e| Error::config(format!("Failed to create config directory: {}", e)))?;
        }

        let content = toml::to_string_pretty(self)
            .map_err(|e| Error::config(format!("Failed to serialize config: {}", e)))?;

        fs::write(&config_path, content)
            .map_err(|e| Error::config(format!("Failed to write config file: {}", e)))?;

        Ok(())
    }
}

/// Get the path to the config file
fn get_config_path() -> Result<PathBuf> {
    let home =
        dirs::home_dir().ok_or_else(|| Error::config("Could not determine home directory"))?;

    Ok(home.join(".maram.toml"))
}

/// Default value helpers for serde
fn default_true() -> bool {
    true
}

fn default_max_file_size() -> u64 {
    1_073_741_824 // 1GB
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_default_config() {
        let config = Config::default();
        assert!(config.display.show_size);
        assert!(config.display.unicode);
        assert_eq!(config.performance.max_file_size, 1_073_741_824);
    }

    #[test]
    fn test_config_serialization() {
        let config = Config::default();
        let toml_str = toml::to_string(&config).unwrap();
        let parsed: Config = toml::from_str(&toml_str).unwrap();

        assert_eq!(config.display.show_size, parsed.display.show_size);
        assert_eq!(config.filters.gitignore, parsed.filters.gitignore);
    }
}

//! Command-line interface argument parsing
//!
//! This module defines all command-line arguments and options for maram
//! using the clap crate with derive macros for a clean, declarative API.

use crate::filters::SortBy;
use crate::formatter::{DistributionFormat, DistributionType, OutputFormat};
use clap::Parser;

/// maram - A modern, high-performance alternative to the Unix tree command
///
/// Recursively displays directory trees with advanced features like per-nested-path limits,
/// inline file sizes and line counts, filtering, sorting, search, and beautiful visualizations.
#[derive(Parser, Debug, Clone)]
#[command(name = "maram")]
#[command(author, version, about, long_about = None)]
#[command(arg_required_else_help = false)]
pub struct Args {
    /// The directory to display (defaults to current directory)
    #[arg(default_value = ".")]
    pub path: String,

    // Display options
    /// Use Unicode characters for tree drawing (default: Unicode)
    #[arg(long, short = 'u')]
    pub unicode: bool,

    /// Enable colored output (auto-detected by default)
    #[arg(long)]
    pub color: bool,

    /// Disable colored output
    #[arg(long, conflicts_with = "color")]
    pub no_color: bool,

    /// Show full absolute paths instead of relative
    #[arg(long, short = 'f')]
    pub full_path: bool,

    // Per-nested-path limits
    /// Maximum number of directories to show per directory
    #[arg(long, value_name = "N")]
    pub max_dirs: Option<usize>,

    /// Maximum number of files to show per directory
    #[arg(long, value_name = "N")]
    pub max_files: Option<usize>,

    // Inline details
    /// Show file sizes (default: on)
    #[arg(long, default_value = "true")]
    pub show_size: bool,

    /// Show line counts for text files
    #[arg(long)]
    pub show_lines: bool,

    /// Show recursive directory sizes
    #[arg(long)]
    pub dir_sizes: bool,

    /// Maximum file size for line counting (default: 1GB)
    #[arg(long, default_value = "1073741824", value_name = "BYTES")]
    pub max_file_size: u64,

    // Filtering options
    /// Include only files matching this regex pattern
    #[arg(long, value_name = "PATTERN")]
    pub include: Option<String>,

    /// Exclude files matching this regex pattern
    #[arg(long, value_name = "PATTERN")]
    pub exclude: Option<String>,

    /// Show only directories
    #[arg(long, conflicts_with = "only_files")]
    pub only_dirs: bool,

    /// Show only files
    #[arg(long, conflicts_with = "only_dirs")]
    pub only_files: bool,

    /// Minimum file size to include (e.g., 1MB, 500KB)
    #[arg(long, value_name = "SIZE")]
    pub min_size: Option<String>,

    /// Maximum file size to include (e.g., 10MB, 1GB)
    #[arg(long, value_name = "SIZE")]
    pub max_size: Option<String>,

    /// Show files newer than specified time (e.g., 1d, 2h, 30m)
    #[arg(long, value_name = "TIME")]
    pub newer_than: Option<String>,

    /// Show files older than specified time (e.g., 1d, 2h, 30m)
    #[arg(long, value_name = "TIME")]
    pub older_than: Option<String>,

    /// Respect .gitignore files
    #[arg(long)]
    pub gitignore: bool,

    /// Show all files including hidden ones
    #[arg(short, long)]
    pub all: bool,

    // Sorting options
    /// Sort files by: name, size, time, ext, or lines
    #[arg(long, value_enum, value_name = "FIELD")]
    pub sort: Option<SortBy>,

    /// Reverse sort order
    #[arg(long, short = 'r')]
    pub reverse: bool,

    // Search options
    /// Search for files matching this regex pattern
    #[arg(long, value_name = "QUERY")]
    pub search: Option<String>,

    /// Case-insensitive search
    #[arg(long, short = 'i', requires = "search")]
    pub ignore_case: bool,

    // Summary options
    /// Show total size summary
    #[arg(long, action = clap::ArgAction::SetTrue)]
    pub total_size: bool,

    // Size distribution
    /// Show size distribution by: type, size, or ext
    #[arg(long, value_enum, value_name = "TYPE")]
    pub dist: Option<DistributionType>,

    /// Number of top items to show in distribution
    #[arg(long, default_value = "10", value_name = "N", requires = "dist")]
    pub top: usize,

    /// Distribution output format: table or chart
    #[arg(
        long,
        value_enum,
        default_value = "chart",
        value_name = "FORMAT",
        requires = "dist"
    )]
    pub format: DistributionFormat,

    // Other options
    /// Maximum depth to traverse
    #[arg(short = 'L', long, value_name = "N")]
    pub depth: Option<usize>,

    /// Output format
    #[arg(long, value_enum, default_value = "tree", value_name = "FORMAT")]
    pub output: OutputFormat,

    /// Number of threads for parallel operations (0 = auto)
    #[arg(long, default_value = "0", value_name = "N")]
    pub threads: usize,

    /// Follow symbolic links
    #[arg(long)]
    pub follow_symlinks: bool,

    /// Show git status colors (requires git repository)
    #[arg(long)]
    pub git_status: bool,

    /// Enable verbose logging
    #[arg(long)]
    pub verbose: bool,

    /// Show timing and performance statistics
    #[arg(long)]
    pub bench: bool,

    /// Continue on errors instead of stopping
    #[arg(long)]
    pub ignore_errors: bool,
}

impl Default for Args {
    fn default() -> Self {
        Self {
            path: ".".to_string(),
            unicode: true,
            color: false,
            no_color: false,
            full_path: false,
