            min_size: None,
            max_size: None,
            newer_than: None,
            older_than: None,
            gitignore: false,
            all: false,
            sort: None,
            reverse: false,
            search: None,
            ignore_case: false,
            total_size: false,
            dist: None,
            top: 10,
            format: DistributionFormat::Chart,
            depth: None,
            output: OutputFormat::Tree,
            threads: 0,
            follow_symlinks: false,
            git_status: false,
            verbose: false,
            bench: false,
            ignore_errors: false,
        }
    }
}
